cat > hooks/useRideHistory.tsx <<'EOF'
import {useCallback, useEffect, useRef, useState} from "react";
import {Log} from "./useLogs.tsx";
import {apiGet, apiPatch, apiPost} from "../services/http.ts";
import {RideHistory, RideHistoryEntry} from "../types/rideHistory.ts";
import {parseDriverPlate, parseFare} from "../utils/driverNotification.ts";

export const useRideHistory = (logs: Log[]) => {
    const [history, setHistory] = useState<RideHistory | undefined>();
    const [error, setError] = useState(false);

    // Entry creation promises by request ID, so the assignment update can wait
    // for the entry to exist, and the requests that were already updated.
    const createdRef = useRef(new Map<number, Promise<RideHistoryEntry | undefined>>());
    const updatedRef = useRef(new Set<number>());

    const refresh = useCallback(async () => {
        try {
            setHistory(await apiGet<RideHistory>(`/ride-history?nonse=${Math.random()}`));
            setError(false);
        } catch (e) {
            console.error("cannot load ride history", e);
            setError(true);
        }
    }, []);

    useEffect(() => {
        refresh();
    }, [refresh]);

    const createEntry = useCallback((requestID: number, pickupLocation: string, dropoffLocation: string,
                                      headers: Record<string, string>) => {
        const created = apiPost<RideHistoryEntry>('/ride-history', {
            pickupLocation,
            dropoffLocation,
            requestTime: new Date().toISOString(),
        }, headers).then(entry => {
            refresh();
            return entry;
        }).catch(e => {
            console.error("cannot create ride history entry", e);
            return undefined;
        });
        createdRef.current.set(requestID, created);
        return created;
    }, [refresh]);

    // When the driver notification of a request arrives, record the plate and fare.
    useEffect(() => {
        logs.forEach(log => {
            const requestID = log.requestID;
            if (updatedRef.current.has(requestID) || !createdRef.current.has(requestID)) return;

            for (const entry of log.entries) {
                if (entry.service !== 'driver') continue;
                const driverPlate = parseDriverPlate(entry.status);
                const fare = parseFare(entry.status);
                if (driverPlate === undefined || fare === undefined) continue;

                updatedRef.current.add(requestID);
                createdRef.current.get(requestID)!.then(async created => {
                    if (!created) return;
                    try {
                        await apiPatch('/ride-history', {id: created.id, driverPlate, fare}, {});
                        await refresh();
                    } catch (e) {
                        console.error("cannot update ride history entry", e);
                    }
                });
                break;
            }
        });
    }, [logs, refresh]);

    return {history, error, createEntry};
};
EOF
